import java.util.ArrayList;
import java.util.List;

public class WhyGenericsDemo {
    public static void main(String[] args) {
        // 1. Raw Type Demonstration (The Danger)
        List rawList = new ArrayList();
        rawList.add("Production User");
        rawList.add(99999); // Contamination! Allowed by raw type

        try {
            for (Object obj : rawList) {
                String str = (String) obj; // Throws ClassCastException on second element!
                System.out.println("Raw user: " + str.toUpperCase());
            }
        } catch (ClassCastException ex) {
            System.out.println("Caught runtime crash from raw type: " + ex.getMessage());
        }

        // 2. Generic Type-Safe Collection (The Modern Standard)
        List<String> safeList = new ArrayList<>();
        safeList.add("Alice");
        safeList.add("Bob");
        // safeList.add(12345); // Rejected by compiler! Cannot break at runtime

        System.out.println("Type-safe generic extraction:");
        for (String user : safeList) {
            // Zero manual casting required!
            System.out.println("Verified user: " + user.toUpperCase());
        }
    }
}
// Expected Output:
// Raw user: PRODUCTION USER
// Caught runtime crash from raw type: class java.lang.Integer cannot be cast to class java.lang.String
// Type-safe generic extraction:
// Verified user: ALICE
// Verified user: BOB

