import java.util.ArrayList;
import java.util.List;

public class SafeMigrationAdapter {
    // Safely migrates raw legacy list to a type-safe String list
    public static List<String> filterStringsOnly(List rawList) {
        List<String> cleanList = new ArrayList<>();
        if (rawList == null) return cleanList;

        for (Object item : rawList) {
            if (item instanceof String) {
                cleanList.add((String) item);
            }
        }
        return cleanList;
    }

    public static void main(String[] args) {
        List legacyPayload = new ArrayList();
        legacyPayload.add("Telemetry_OK");
        legacyPayload.add(404); // Bad payload
        legacyPayload.add("System_Online");

        List<String> sanitized = filterStringsOnly(legacyPayload);
        System.out.println("Sanitized count: " + sanitized.size());
        for (String msg : sanitized) {
            System.out.println("Message: " + msg);
        }
    }
}

