import java.util.List;
import java.util.ArrayList;

public class TypeFilter {
    public static <T> List<T> filterByType(List<?> items, Class<T> targetClass) {
        List<T> result = new ArrayList<>();
        if (items == null || targetClass == null) return result;

        for (Object item : items) {
            if (targetClass.isInstance(item)) {
                result.add(targetClass.cast(item));
            }
        }
        return result;
    }

    public static void main(String[] args) {
        List<Object> mixed = List.of("hello", 42, "world", 3.14, "java");
        List<String> strings = filterByType(mixed, String.class);
        System.out.println(strings);
    }
}

