import java.util.List;
import java.util.ArrayList;

public class ContaminationAuditor {
    public static int countContaminants(List rawList, Class<?> expectedType) {
        if (rawList == null || expectedType == null) return 0;
        int count = 0;
        for (Object item : rawList) {
            if (item == null || !expectedType.isInstance(item)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        List raw = new ArrayList();
        raw.add("valid1");
        raw.add(100);
        raw.add("valid2");
        raw.add(true);
        System.out.println(countContaminants(raw, String.class));
    }
}

