import java.util.List;

public class NumberSumCalculator {
    public static double sumNumbers(List<? extends Number> numbers) {
        if (numbers == null) return 0.0;
        double sum = 0.0;
        for (Number num : numbers) {
            if (num != null) {
                sum += num.doubleValue();
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(10, 20, 30);
        List<Double> doubles = List.of(1.5, 2.5, 3.0);
        System.out.println(sumNumbers(ints));
        System.out.println(sumNumbers(doubles));
    }
}

