import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class TypeSafeMap {
    private final Map<Class<?>, Object> values = new HashMap<>();

    public <T> void put(Class<T> type, T instance) {
        Objects.requireNonNull(type, "Type token cannot be null");
        values.put(type, instance);
    }

    public <T> T get(Class<T> type) {
        Objects.requireNonNull(type, "Type token cannot be null");
        return type.cast(values.get(type));
    }

    public static void main(String[] args) {
        TypeSafeMap map = new TypeSafeMap();
        map.put(String.class, "Java 21");
        map.put(Integer.class, 2024);
        System.out.println(map.get(String.class));
        System.out.println(map.get(Integer.class));
    }
}

