import java.util.List;

public class FirstInstanceFinder {
    public static <T> T findFirstOfType(List<?> items, Class<T> type) {
        if (items == null || type == null) return null;
        for (Object item : items) {
            if (type.isInstance(item)) {
                return type.cast(item);
            }
        }
        return null;
    }

    public static void main(String[] args) {
        List<Object> items = List.of(1, 2, "found_me", 4, "skip_me");
        String result = findFirstOfType(items, String.class);
        System.out.println(result);
    }
}
